$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$launcher=Join-Path $PSScriptRoot 'run_local.ps1';$runRoot=Join-Path $root 'logs/rsl_rl/unitree_b2w_stair';$bench=Join-Path $root 'logs/stair_benchmark';$outDir=Join-Path $root 'logs/stair_slow_brake_wheel_screen_20260923';New-Item -ItemType Directory -Force $outDir|Out-Null
$parents=@([pscustomobject]@{Seed=54;Directory='2026-09-23_11-02-18_stair_basevel_control57_2048_20260923_seed54_full';Sha='49c50eabfc3d9ce640dc3cc46fb15f45fb8f071351e53a768afc2a406b474801'},[pscustomobject]@{Seed=55;Directory='2026-09-23_11-04-25_stair_basevel_control57_2048_20260923_seed55_full';Sha='f5d7403f98853374b3cdaf6dc329461b29f0f0658e308c0d6a47b890c2371ff2'})
