foreach($profile in $profiles){$jobs=@();foreach($parent in $parents){$cp=Join-Path (Join-Path $runRoot $parent.Directory) 'model_398.pt';if((Get-FileHash $cp -Algorithm SHA256).Hash.ToLowerInvariant()-ne$parent.Sha){throw 'Parent hash mismatch'};$label="$($profile.Name)_control57_s$($parent.Seed)_screen14x32";if(Get-ChildItem $bench -Filter "${label}_cycle_*.json" -ErrorAction SilentlyContinue){throw "Output exists for $label"};$stdout=Join-Path $outDir "$label.stdout.log";$stderr=Join-Path $outDir "$label.stderr.log";$cli=@('-NoProfile','-ExecutionPolicy','Bypass','-File',('"'+$launcher+'"'),'scripts/eval_stair_suite.py','--checkpoint',('"'+$cp+'"'),'--label',$label,'--config','configs/stair_eval_v3_screen_14_32.json','--split','development','--brake-profile','--brake-distance','1.2','--brake-min-speed','0.15','--hold-wheel-action-scale',$profile.Scale,'--hold-wheel-ramp-steps',$profile.Ramp);$p=Start-Process powershell.exe -ArgumentList $cli -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$jobs+=[pscustomobject]@{Label=$label;Process=$p};Write-Output "START $label PID=$($p.Id) actor=57 action=16"};foreach($j in $jobs){$j.Process.WaitForExit();$j.Process.Refresh();$files=@(Get-ChildItem $bench -Filter "$($j.Label)_cycle_*.json");if($j.Process.ExitCode-ne0-or$files.Count-ne2){throw "Screen failed: $($j.Label)"};$r=@($files|ForEach-Object{Get-Content $_.FullName -Raw|ConvertFrom-Json});Write-Output "DONE $($j.Label) passage=$(($r|Measure-Object passage_success -Sum).Sum)/256 cycle=$(($r|Measure-Object success -Sum).Sum)/256 unsafe=$(($r|Measure-Object unsafe -Sum).Sum) stop_failed=$(($r|Measure-Object stop_failed -Sum).Sum) incomplete=$(($r|Measure-Object incomplete -Sum).Sum)"}}
